_🛠️ Refactor suggestion_

_⚠️ Potential issue_

**Harden delete flow: add capability check, unslash/sanitize inputs, and block restricted keys**

Nonce is verified, but we should also:
- Enforce a capability check before destructive actions.
- Use wp_unslash() before sanitization for superglobals.
- Prevent deletion of restricted/customer-internal meta keys.

Apply:

```diff
 public function page_loaded() {

   // Handle delete meta field action
   if (isset($_GET['delete_meta_key']) && isset($_GET['_wpnonce'])) {

-    $meta_key = sanitize_key($_GET['delete_meta_key']);
-    $nonce = sanitize_text_field($_GET['_wpnonce']);
+    $meta_key = sanitize_key(wp_unslash($_GET['delete_meta_key']));
+    $nonce    = sanitize_text_field(wp_unslash($_GET['_wpnonce']));

     // Verify nonce for security
     if ( ! wp_verify_nonce($nonce, 'delete_customer_meta_' . $meta_key)) {
       wp_die(__('Security check failed. Please try again.', 'multisite-ultimate'));
     }

+    // Ensure the current user can manage customers.
+    if ( ! current_user_can('wu_edit_customers')) {
+      wp_die(esc_html__('You do not have permission to edit customers.', 'multisite-ultimate'));
+    }
+
     $customer = $this->get_object();
     if ($customer) {
+      // Disallow deleting protected keys programmatically even if a link is constructed.
+      if ($this->restricted_customer_meta_keys($meta_key)) {
+        $redirect_url = add_query_arg(
+          [
+            'updated' => 'meta_delete_forbidden',
+            'tab'     => 'custom_meta',
+          ],
+          wu_network_admin_url('wp-ultimo-edit-customer', ['id' => $customer->get_id()])
+        );
+        wp_safe_redirect($redirect_url);
+        exit;
+      }
+
       $deleted = wu_delete_customer_meta($customer->get_id(), $meta_key);

       $redirect_args = [
         'updated' => $deleted ? 'meta_deleted' : 'meta_delete_failed',
         'tab'     => 'custom_meta'
       ];

       $redirect_url = add_query_arg($redirect_args, wu_network_admin_url('wp-ultimo-edit-customer', ['id' => $customer->get_id()]));

       wp_safe_redirect($redirect_url);
       exit;
     }
   }

   // Call parent to preserve existing functionality (e.g., adding new fields)
   parent::page_loaded();
 }
```

